//! Generated error codes and i18n keys shared by all crates.
//!
//! `ErrorCode` and `Group` are generated by `build.rs` from `errors/error-codes.toml`
//! (blueprint section 11), the constants in [`i18n`] from `locales/en/*.ftl` (section 13). Every crate maps its own error enum onto `ErrorCode` via [`Coded`].

mod consts;

use consts::{
    CLASS_CONFLICT, CLASS_EXTERNAL, CLASS_INTERNAL, CLASS_INVALID_INPUT, CLASS_LIMIT,
    CLASS_NOT_FOUND, CLASS_PERMISSION, SEVERITY_ERROR, SEVERITY_INFO, SEVERITY_WARNING,
};

/// Error class, the hundreds digit of a code (blueprint 11.2).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
#[repr(u8)]
pub enum Class {
    /// Invalid input or validation failure.
    InvalidInput = CLASS_INVALID_INPUT,
    /// Not found or unavailable.
    NotFound = CLASS_NOT_FOUND,
    /// Conflict or invalid state.
    Conflict = CLASS_CONFLICT,
    /// Authentication or permission problem.
    Permission = CLASS_PERMISSION,
    /// Limit, timeout or resource problem.
    Limit = CLASS_LIMIT,
    /// An external system failed.
    External = CLASS_EXTERNAL,
    /// Internal error (bug).
    Internal = CLASS_INTERNAL,
}

impl Class {
    /// The class digit as it appears in the code id.
    #[must_use]
    pub const fn digit(self) -> u8 {
        self as u8
    }
}

/// How serious a code is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Severity {
    /// A failure.
    Error,
    /// A condition that did not stop the operation.
    Warning,
    /// Informational only.
    Info,
}

impl Severity {
    /// Lower-case label as used in the registry and in API output.
    #[must_use]
    pub const fn label(self) -> &'static str {
        match self {
            Self::Error => SEVERITY_ERROR,
            Self::Warning => SEVERITY_WARNING,
            Self::Info => SEVERITY_INFO,
        }
    }
}

/// Static data of one error code, as returned by [`ErrorCode::entry`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Entry {
    /// Id such as `SRC-201`.
    pub id: &'static str,
    /// Group of the code.
    pub group: Group,
    /// Class of the code.
    pub class: Class,
    /// Severity.
    pub severity: Severity,
    /// Whether retrying can succeed.
    pub retryable: bool,
    /// English developer description.
    pub description: &'static str,
    /// First release containing the code.
    pub since: &'static str,
    /// `true` for retired codes.
    pub deprecated: bool,
    /// Fluent message key, `error-<id>`.
    pub message_key: &'static str,
}

/// Static data of one code group, as returned by [`Group::info`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroupInfo {
    /// Id prefix such as `SRC`.
    pub prefix: &'static str,
    /// English title of the group.
    pub title: &'static str,
    /// Crate or area that owns the group.
    pub owner: &'static str,
}

impl Group {
    /// Id prefix such as `SRC`.
    #[must_use]
    pub const fn prefix(self) -> &'static str {
        self.info().prefix
    }

    /// English title of the group.
    #[must_use]
    pub const fn title(self) -> &'static str {
        self.info().title
    }
}

/// Generated code. It is exempt from the function-length and doc-markdown lints only:
/// the registry data forms one long `match`, and descriptions are free text.
#[allow(
    clippy::too_many_lines,
    clippy::doc_markdown,
    reason = "generated code"
)]
mod generated {
    use super::{Class, Entry, GroupInfo, Severity};

    include!(concat!(env!("OUT_DIR"), "/error_codes.rs"));
}

pub use generated::{ErrorCode, Group};

/// Message keys of all Fluent files except the error messages, generated from `locales/en`
/// (blueprint section 13). An unknown key does not compile.
pub mod i18n {
    include!(concat!(env!("OUT_DIR"), "/i18n_keys.rs"));
}

impl ErrorCode {
    /// Id such as `SRC-201`.
    #[must_use]
    pub const fn id(self) -> &'static str {
        self.entry().id
    }

    /// Group of the code.
    #[must_use]
    pub const fn group(self) -> Group {
        self.entry().group
    }

    /// Class of the code.
    #[must_use]
    pub const fn class(self) -> Class {
        self.entry().class
    }

    /// Severity of the code.
    #[must_use]
    pub const fn severity(self) -> Severity {
        self.entry().severity
    }

    /// Whether retrying the operation can succeed.
    #[must_use]
    pub const fn retryable(self) -> bool {
        self.entry().retryable
    }

    /// English developer description for logs and MCP responses.
    #[must_use]
    pub const fn description(self) -> &'static str {
        self.entry().description
    }

    /// Fluent key of the user-facing message, `error-<id>`.
    #[must_use]
    pub const fn message_key(self) -> &'static str {
        self.entry().message_key
    }
}

/// Implemented by every crate error type; each variant maps to exactly one code.
pub trait Coded {
    /// The registered code of this error.
    fn code(&self) -> ErrorCode;
}
